import{_ as t,o as a,c as d,ag as i}from"./chunks/framework.DHSXpJLs.js";const k=JSON.parse('{"title":"REST API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rest-api.md","filePath":"reference/rest-api.md","lastUpdated":1790781261000}'),s={name:"reference/rest-api.md"};function o(r,e,c,n,h,p){return a(),d("div",null,[...e[0]||(e[0]=[i(`<h1 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h1><p>Go server（默认 <code>http://localhost:8090</code>）是平台唯一对外入口，对外路径统一 <code>/api/v1/{resource}/{id}</code>。本页讲跨资源共用的约定：端点地图、响应 envelope、错误码、鉴权与 CORS、机器可消费 schema。</p><h2 id="端点地图" tabindex="-1">端点地图 <a class="header-anchor" href="#端点地图" aria-label="Permalink to &quot;端点地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>路径前缀</th><th>契约</th></tr></thead><tbody><tr><td>模型</td><td><code>/api/v1/models</code></td><td><a href="/SourceAEC/reference/api-model">模型与审查 API</a></td></tr><tr><td>Issue</td><td><code>/api/v1/models/{id}/issues</code></td><td><a href="/SourceAEC/reference/api-model">模型与审查 API</a></td></tr><tr><td>属性 override 与修改记录</td><td><code>/api/v1/models/{id}/overrides</code>、<code>/changes</code>、<code>/entities/{entityId}/properties</code></td><td><a href="/SourceAEC/reference/api-model">模型与审查 API</a></td></tr><tr><td>脚本编辑（代理）</td><td><code>/api/v1/models/{id}/script/...</code></td><td><a href="/SourceAEC/reference/edit-api">IFC 编辑 API</a></td></tr><tr><td>编辑只读与对比（代理）</td><td><code>/api/v1/models/{id}/edit/...</code></td><td><a href="/SourceAEC/reference/edit-api">IFC 编辑 API</a></td></tr><tr><td>对话与项目</td><td><code>/api/v1/chat/...</code>、<code>/api/v1/projects/...</code></td><td><a href="/SourceAEC/reference/api-chat">对话 API</a></td></tr><tr><td>静态资源</td><td><code>/v1/models/{id}/...</code></td><td><a href="/SourceAEC/reference/api-model">模型与审查 API</a></td></tr></tbody></table><p>模型 id 格式是 <code>^m_[0-9a-f]{16}$</code>，服务端据此校验以防路径穿越。</p><h2 id="响应与错误码" tabindex="-1">响应与错误码 <a class="header-anchor" href="#响应与错误码" aria-label="Permalink to &quot;响应与错误码&quot;">​</a></h2><p>除静态文件端点外，所有响应统一 envelope，<code>code=0</code> 表示成功：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>code</th><th>含义</th></tr></thead><tbody><tr><td><code>40001</code></td><td>参数或校验错误。编辑服务的 422 经代理也映射为此</td></tr><tr><td><code>40002</code></td><td>超限，如上传大小</td></tr><tr><td><code>40100</code></td><td>鉴权失败</td></tr><tr><td><code>40400</code></td><td>模型或资源不存在</td></tr><tr><td><code>40900</code></td><td>冲突</td></tr><tr><td><code>50000</code></td><td>服务器内部错误</td></tr><tr><td><code>50200</code></td><td>编辑服务不可达等代理错误</td></tr><tr><td><code>50400</code></td><td>编辑服务超时</td></tr></tbody></table><p>代理映射的完整规则见 <a href="/SourceAEC/development/server">Go Server</a>。</p><h2 id="鉴权与-cors" tabindex="-1">鉴权与 CORS <a class="header-anchor" href="#鉴权与-cors" aria-label="Permalink to &quot;鉴权与 CORS&quot;">​</a></h2><p>鉴权默认关闭。设置 <code>apiToken</code>（或 <code>VIEWER_API_TOKEN</code>）后，所有端点都要求 <code>Authorization: Bearer &lt;token&gt;</code>，只有 OPTIONS 预检和<strong>四类只读文件端点</strong>豁免——xeokit 和 <code>&lt;img&gt;</code> 标签带不了请求头：</p><ul><li><code>GET /v1/models/{id}/model.xkt</code></li><li><code>GET /v1/models/{id}/metadata.json</code></li><li><code>GET /v1/models/{id}/render.json</code></li><li><code>GET /v1/models/{id}/issues/{file}</code></li></ul><p>浏览器端把 token 存在 localStorage 的 <code>aiifc_token</code> 键，遇到 401 会弹输入框，保存后自动重试原请求。chat 的事件流走 EventSource，没法带自定义头，<strong>这是唯一放行 <code>?token=</code> 查询参数的路径</strong>。</p><p>CORS 是白名单制，用 <code>corsOrigins</code>（或 <code>VIEWER_CORS_ORIGINS</code>）配置，逗号分隔。两个 Python 编辑服务自身没有鉴权，安全完全靠只监听 127.0.0.1，不要把它们暴露到网络上。</p><h2 id="机器可消费-openapi" tabindex="-1">机器可消费 OpenAPI <a class="header-anchor" href="#机器可消费-openapi" aria-label="Permalink to &quot;机器可消费 OpenAPI&quot;">​</a></h2><h3 id="edit-service" tabindex="-1">edit-service <a class="header-anchor" href="#edit-service" aria-label="Permalink to &quot;edit-service&quot;">​</a></h3><p>完整 schema 见 <a href="/SourceAEC/ai-tools.openapi.json">ai-tools.openapi.json</a>，由 FastAPI 直接导出，与运行中服务的 <code>GET /openapi.json</code> 一致；渲染成文档的版本见<a href="/SourceAEC/reference/edit-api-reference">编辑 API 参考</a>。编辑 API 变更后重新生成：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services/ifc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/export_openapi.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 输出到 docs/site/public/ai-tools.openapi.json</span></span></code></pre></div><h3 id="go-server" tabindex="-1">Go server <a class="header-anchor" href="#go-server" aria-label="Permalink to &quot;Go server&quot;">​</a></h3><p>完整 schema 见 <a href="/SourceAEC/go-server.openapi.json">go-server.openapi.json</a>，可以直接喂给 LLM、工具或代码生成器。路由清单与请求响应 schema 随公开文档版本发布；修改 Go API 时，请同步更新 <code>docs/site/public/</code> 下的 schema、路由清单和对应参考页，并运行 <code>npm run docs:build</code> 检查站点。</p><p>对接方要自研前端或接自己的存储时，看<a href="/SourceAEC/development/integration">存储与前端对接</a>；AI agent 接入看 <a href="/SourceAEC/reference/ai">AI 接入</a>。</p>`,22)])])}const u=t(s,[["render",o]]);export{k as __pageData,u as default};
